import{_ as e,o as a,c as r,a6 as o}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"四张脸谱 · DeepSeek / Llama / Qwen / GLM 的组合拳","description":"把散落在各维度的选择收拢成整体——DeepSeek 的“效率最大化”、Llama 的“务实标准派”、Qwen 的“多语言 + 实用主义”、GLM 的“借力 DeepSeek、稳字当头”，以及 2026 年三大旗舰（DeepSeek V4.1-Flash、Qwen3.8-Max、Kimi K3）的架构进化。","frontmatter":{"title":"四张脸谱 · DeepSeek / Llama / Qwen / GLM 的组合拳","description":"把散落在各维度的选择收拢成整体——DeepSeek 的“效率最大化”、Llama 的“务实标准派”、Qwen 的“多语言 + 实用主义”、GLM 的“借力 DeepSeek、稳字当头”，以及 2026 年三大旗舰（DeepSeek V4.1-Flash、Qwen3.8-Max、Kimi K3）的架构进化。","source":"https://daiw.org/manual/llm-anatomy/model-profiles"},"headers":[],"relativePath":"manual/llm/llm-anatomy/model-profiles.md","filePath":"manual/llm/llm-anatomy/model-profiles.md"}'),n={name:"manual/llm/llm-anatomy/model-profiles.md"};function l(s,t,i,g,d,m){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="四张脸谱-·-deepseek-llama-qwen-glm-的组合拳" tabindex="-1">四张脸谱 · DeepSeek / Llama / Qwen / GLM 的组合拳 <a class="header-anchor" href="#四张脸谱-·-deepseek-llama-qwen-glm-的组合拳" aria-label="Permalink to &quot;四张脸谱 · DeepSeek / Llama / Qwen / GLM 的组合拳&quot;">​</a></h1><blockquote><p>把散落在各维度的选择收拢成整体——DeepSeek 的“效率最大化”、Llama 的“务实标准派”、Qwen 的“多语言 + 实用主义”、GLM 的“借力 DeepSeek、稳字当头”，以及 2026 年三大旗舰（DeepSeek V4.1-Flash、Qwen3.8-Max、Kimi K3）的架构进化。</p></blockquote><p>前面我们一直“横切”——一维一维地对比。这一章反过来“竖看”：把每个模型散落在各维度的选择<strong>收拢成一个整体</strong>，看它作为一个“人”的性格。你会发现，<strong>每个模型的风格，不是某一个绝招，而是一连串取舍叠出来的组合拳。</strong></p><h2 id="deepseek-v3-→-v4-1-flash-效率最大化的偏执狂" tabindex="-1">DeepSeek（V3 → V4.1-Flash）：效率最大化的偏执狂 <a class="header-anchor" href="#deepseek-v3-→-v4-1-flash-效率最大化的偏执狂" aria-label="Permalink to &quot;DeepSeek（V3 → V4.1-Flash）：效率最大化的偏执狂&quot;">​</a></h2><p><strong>一句话性格：每一个选择，都在问“怎么用更少，办更多”。</strong></p><p>把 DeepSeek-V3 的选择连起来看，主题惊人地一致：</p><ul><li><strong>MLA</strong>：把 KV 缓存压到比 GQA 还小，质量还反超 MHA；</li><li><strong>细粒度 MoE</strong>（256 专家 / 激活 8+1、含共享专家）：极致专精，671B 只激活 37B；</li><li><strong>无辅助损失均衡</strong>：不牺牲质量地解决 MoE 负载；</li><li><strong>前 3 层稠密</strong>：稳住训练地基；</li><li><strong>FP8 训练 + MTP</strong>：把训练成本和样本效率再榨一道。</li></ul><p>到了 2026 年的 <strong><a href="https://daiw.org/manual/deepseek-v4-flash" target="_blank" rel="noreferrer">DeepSeek V4.1-Flash</a></strong>，这种“抠门到极致”的效率哲学更是武装到了牙齿：把 40 层切成 <strong>20 层编码器 + 20 层解码器（CED）</strong>，解码算力直接减半；用 <strong>CSA2</strong> 跨层共享 FP4 KV 缓存，把每 token 缓存从 70.3 KB 砍到 <strong>890 字节</strong>；把死记硬背的知识剥离给可卸载到内存的 99B <strong>Engram</strong> 查表记忆；再用 4.3B 的并行草稿头 <strong>DSpark</strong> 替代串行 MTP。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>签名动作：MLA / CSA2 + 极致软硬协同。</strong> DeepSeek 证明了“顶尖大模型”和“训得起、跑得起”不矛盾——靠的不是某一招，而是<strong>省 KV 缓存、省激活、省精度、省串行步数</strong>这一整套叠满 buff 的组合。它是这份名单里旗帜鲜明的“效率派”。</p></div><h2 id="llama-3-→-4-务实的标准制定者" tabindex="-1">Llama（3 → 4）：务实的标准制定者 <a class="header-anchor" href="#llama-3-→-4-务实的标准制定者" aria-label="Permalink to &quot;Llama（3 → 4）：务实的标准制定者&quot;">​</a></h2><p><strong>一句话性格：不追新奇，把成熟方案做扎实，顺手定义“默认”。</strong></p><ul><li><strong>Llama 3</strong>：一个<strong>教科书级的稠密 GQA 模型</strong>——RoPE、RMSNorm、Pre-Norm、SwiGLU、无 bias，干净、标准、开放。它某种程度上就是本专栏<a href="/Front2Full/manual/llm/llm-anatomy/common-skeleton">“共同骨架”</a>那张表的活标本，也是无数模型的对标基线。</li><li><strong>Llama 4</strong>：转向 <strong>MoE</strong>，但走的是<strong>保守路线</strong>——8 个大专家、激活 2 个、无共享专家、MoE 与稠密层交替。相比 DeepSeek 的“多而小”，Llama 4 是“少而大”的经典派。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>签名动作：定义默认。</strong> Llama 的价值常不在“最先”，而在“最稳、最开放、最好复现”。它是那种“你不确定该怎么选时，照它抄准没错”的标准件。</p></div><h2 id="qwen-2-5-→-3-→-3-8-max-多语言底色-务实应变" tabindex="-1">Qwen（2.5 → 3 → 3.8-Max）：多语言底色，务实应变 <a class="header-anchor" href="#qwen-2-5-→-3-→-3-8-max-多语言底色-务实应变" aria-label="Permalink to &quot;Qwen（2.5 → 3 → 3.8-Max）：多语言底色，务实应变&quot;">​</a></h2><p><strong>一句话性格：为多语言（尤其中文）而生，一切服从当前规模下的实测收益。</strong></p><ul><li><strong>大词表（152K → 248K）</strong>：覆盖中文/多语言/代码更好——这是它“服务谁”写在脸上的印记；</li><li><strong>Qwen2 给 QKV 加回 bias</strong>：为长度外推；</li><li><strong>QK-Norm、偏深的结构</strong>：求稳、求抽象深度；</li><li><strong>共享专家的取舍</strong>：Qwen3（128 专家）觉得共享专家收益不明，主动砍掉图简单；到了 2026 年的 <strong><a href="https://daiw.org/manual/qwen3-8-max" target="_blank" rel="noreferrer">Qwen3.8-Max</a></strong>（2.4T 总参数、512 路由专家选 10），在超细粒度稀疏下<strong>果断把 1 个共享专家请了回来</strong>，并换上 <strong>3:1 Gated DeltaNet + Gated Attention</strong> 混合栈。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>签名动作：不教条的实用主义。</strong> 在 128 专家时它敢砍共享专家，在 512 专家时它又敢加回来——Qwen 的判断从不拘泥于口号，一切服从“在我这一代配方和规模下，到底值不值”。</p></div><h2 id="glm-4-5-借力打力-稳字当头" tabindex="-1">GLM（4.5）：借力打力，稳字当头 <a class="header-anchor" href="#glm-4-5-借力打力-稳字当头" aria-label="Permalink to &quot;GLM（4.5）：借力打力，稳字当头&quot;">​</a></h2><p><strong>一句话性格：把别人验证过的好东西拿来，拼一套稳的。</strong></p><ul><li><strong>MoE + 共享专家</strong>、<strong>前几层稠密</strong>：这两招<strong>明说借鉴自 DeepSeek</strong>——“大 MoE 里，稠密的头几层能改善收敛稳定性”；</li><li><strong>GQA + QK-Norm</strong>：主流稳妥组合；</li><li><strong>保留了 GPT-2 时代的注意力 bias</strong>：一点传承的执念。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>签名动作：站在巨人肩上求稳。</strong> GLM-4.5 不追求哪一维“最激进”，而是把 DeepSeek 等验证过的稳定性设计<strong>组装</strong>起来，做一个可靠的大 MoE。它代表了一种健康的工程心态：<strong>创新不必事事原创，把对的东西拼对，也是本事。</strong></p></div><h2 id="_2026-进阶加映-kimi-k2-→-k3-k3-1-pro-的算法破局派" tabindex="-1">2026 进阶加映：Kimi（K2 → K3 / K3.1 Pro）的算法破局派 <a class="header-anchor" href="#_2026-进阶加映-kimi-k2-→-k3-k3-1-pro-的算法破局派" aria-label="Permalink to &quot;2026 进阶加映：Kimi（K2 → K3 / K3.1 Pro）的算法破局派&quot;">​</a></h2><p>如果看完上面四家，再看 Moonshot 的 <strong><a href="https://daiw.org/manual/kimi-k3" target="_blank" rel="noreferrer">Kimi K3 / K3.1 Pro</a></strong>（2.8T 总参数、104B 激活），你会看到第五种鲜明的性格：<strong>用优化器与线性代数重写扩展律</strong>。</p><ul><li><strong>3:1 KDA + Gated MLA / Gated DSA</strong>：69 层通道级遗忘门线性注意力 + 24 层全局/动态稀疏注意力；</li><li><strong>LatentMoE</strong>：把 token 先压到 3,584 维潜空间再走 896 选 16 路由，跨卡 All-to-All 通信砍半；</li><li><strong>AttnRes</strong>：用跨层 softmax 注意力残差取代用了十年的固定加法残差；</li><li><strong>Muon + 原生 MXFP4</strong>：把二阶正交化优化器和 4-bit 微缩放浮点推上 2.8T 规模。</li></ul><h2 id="五张脸谱-一张对照" tabindex="-1">五张脸谱，一张对照 <a class="header-anchor" href="#五张脸谱-一张对照" aria-label="Permalink to &quot;五张脸谱，一张对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型家族</th><th>注意力代表方案</th><th>前馈代表方案</th><th>签名性格</th><th>深度专题</th></tr></thead><tbody><tr><td><strong>DeepSeek（V3 → V4.1-Flash）</strong></td><td><strong>MLA → CSA2（跨层共享 FP4）</strong></td><td>细粒度 MoE（256/8+1 → 384/6+1）+ Engram</td><td>效率最大化</td><td><a href="https://daiw.org/manual/deepseek-v4-flash" target="_blank" rel="noreferrer">《DeepSeek V4.1 Flash 深度解析》</a></td></tr><tr><td><strong>Llama（3 → 4）</strong></td><td>GQA</td><td>3 稠密 → 4 转 MoE（8/2，大，无共享）</td><td>务实标准派</td><td>—</td></tr><tr><td><strong>Qwen（2.5 → 3 → 3.8-Max）</strong></td><td>GQA → <strong>3:1 Gated DeltaNet + Gated Attn</strong></td><td>128/8（无共享）→ <strong>512/10+1（请回共享）</strong>，大词表</td><td>多语言 + 实用主义</td><td><a href="https://daiw.org/manual/qwen3-8-max" target="_blank" rel="noreferrer">《Qwen3.8-Max 深度解析》</a></td></tr><tr><td><strong>GLM（4.5）</strong></td><td>GQA + QK-Norm</td><td>MoE（共享 + 前几层稠密，借鉴 DeepSeek）</td><td>借力求稳</td><td>—</td></tr><tr><td><strong>Kimi（K2 → K3 / K3.1 Pro）</strong></td><td>MLA → <strong>3:1 KDA + Gated MLA / DSA</strong></td><td><strong>LatentMoE（896/16+2，潜空间路由）</strong></td><td>优化器与算法破局派</td><td><a href="https://daiw.org/manual/kimi-k3" target="_blank" rel="noreferrer">《Kimi K3 深度解析》</a></td></tr></tbody></table><p>看到了吗？<strong>同样的六个维度，五种填法，五种性格。</strong> 这正是本专栏想让你获得的能力：拿到任何一个新模型的技术报告，你都能顺着这几个维度快速定位它“像谁、在哪儿下了不一样的注、为什么”。</p><p>最后一章，我们把所有维度汇成一张总表，并收束贯穿全篇的两条主线与几个大趋势，给这趟“解构之旅”画个句号。👉 <a href="/Front2Full/manual/llm/llm-anatomy/recap-and-trends">一张大表 + 趋势</a></p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] DeepSeek-AI. “DeepSeek-V3 Technical Report.” 2024. arXiv:2412.19437.</li><li>[2] Grattafiori et al. (Meta). “The Llama 3 Herd of Models.” 2024. arXiv:2407.21783.</li><li>[3] Qwen Team. “Qwen2.5 Technical Report.” 2024. arXiv:2412.15115.</li><li>[4] Team GLM, Zhipu AI. “ChatGLM: A Family of Large Language Models from GLM-130B to GLM-4 All Tools.” 2024. arXiv:2406.12793.</li><li>[5] Raschka, S. “The Big LLM Architecture Comparison.” 2025. <a href="https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison" target="_blank" rel="noreferrer">https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison</a></li></ul>',30)])])}const k=e(n,[["render",l]]);export{h as __pageData,k as default};
